"""Replace introductory positioning; move detailed local comparisons to supplement."""
from pathlib import Path
from retained_prefix_workflow import D,read,write,sha
from datetime import datetime,timezone
p=D/'paper';parent=read(D/'mechanism_inputs_paper_binding_04.json');old=(p/'current_repair_main.tex').read_text()
assert old==(Path(parent['snapshot'])/'current_repair_main.tex').read_text()
root=D/'routing_related_work_01';root.mkdir(exist_ok=False)
start=old.index('VTR supplies routing and timing infrastructure');end=old.index('\\section{Method:')
intro=r'''VTR supplies routing and STA infrastructure~\cite{vtr9paper}; LaZagna models configurable vertical SB/CB architectures~\cite{lazagna}, while Escaping Flatland improves 3D placement~\cite{flatland}. We hold architecture, packing and placement fixed. Reduced resource occupancy does not imply silicon-area or power savings.

PathFinder negotiates congestion using timing priorities~\cite{pathfinder}. Critical-connection repair after PathFinder predates this work~\cite{liurepair}. AIR preserves legal subtrees, reroutes illegal or delay-degraded connections, and improves existing routes through multiple convergences~\cite{air}. CRoute uses timing-driven connection-based routing~\cite{croute}. Current timing, retained trees and incremental rerouting are therefore established ingredients. Our comparison concerns conditional vertical sharing domains, per-net domain release and capacity-certified owner scopes, with whole-candidate acceptance under fixed timing/resource envelopes. We do not claim a new native router or measured superiority over these external implementations.

Poolad et al. introduce explicit CHANZ resources and multi-die-aware lookahead~\cite{multidie}. Our edge-encoded two-layer results do not validate those architectures or their lookahead. The contributions supported here are matched local mechanism effects, complete resource/time tradeoffs and explicit failure/applicability accounting. The fully integrated frozen controller remains a confirmation target.
'''
new=old[:start]+intro+old[end:]
old_scope=next(x for x in old.splitlines() if x.startswith('Reducing that intervention to two connections'))
new_scope='A two-connection intervention produces 2070657 wire at the same vertical counts and full vector in both native arms and a separate BFS construction. It is legal but dominated by the five-connection result. Fewer queries did not reduce the measured core time. Detailed paths, core timings and audits remain in the supplement; shared diagnostic costs are not complete-flow measurements.'
old_group=next(x for x in old.splitlines() if x.startswith('A 64-connection budget improves'))
new_group='A 64-connection budget reduces 462 to 54 queries in one local scope, yet worsens a complete BNN domain trajectory by 46 wire at equal CPD/SB/CB. Imported workflow time rises from 7099.32 to 10568.53 s. Both trajectories execute the same 2722-query multiset in 18 versus 32 transactions; extra loading, STA and audits erase the local query intuition. The other three cohort endpoints match K 8 quality. These are descriptive development times, not statistical speedups; the divergence history is in the supplement.'
new=new.replace(old_scope,new_scope).replace(old_group,new_group)
new=new.replace(r'\begin{thebibliography}{4}',r'\begin{thebibliography}{9}')
refs=r'''\bibitem{liurepair} Y. Liu, H. Yang, W. Yu, X. Cui, and J. Huang, ``An FPGA timing routing algorithm based on PathFinder and rip-up and retry approach,'' \emph{J. Computer-Aided Design \& Computer Graphics}, vol.26, no.1, pp.138--145, 2014.
\bibitem{air} K. E. Murray, S. Zhong, and V. Betz, ``AIR: A fast but lazy timing-driven FPGA router,'' in \emph{Proc. ASP-DAC}, 2020, pp.338--344.
\bibitem{croute} D. Vercruyce, E. Vansteenkiste, and D. Stroobandt, ``CRoute: A fast high-quality timing-driven connection-based FPGA router,'' in \emph{Proc. FCCM}, 2019, pp.53--60, doi:10.1109/FCCM.2019.00017.
\bibitem{lazagna} I. Youssef, H. Yang, and C. Hao, ``LaZagna: An open-source framework for flexible 3D FPGA architectural exploration,'' in \emph{Proc. ICCAD}, 2025, pp.1--9, doi:10.1109/ICCAD66269.2025.11240893.
\bibitem{multidie} A. Poolad, S. Gholami Shahrouz, A. Boutros, and V. Betz, ``Modeling, optimizing and exploring multi-die FPGA routing architectures,'' arXiv:2606.06421v3, 2026.
'''
new=new.replace('\\end{thebibliography}',refs+'\\end{thebibliography}')
source=p/'current_repair_routing_position_05.tex';assert not source.exists();source.write_text(new)
