 dict(key='air',url='https://csuncle.com/uploads/aspdac2020/pdf/p338_5C-2.pdf',author_url='https://www.eecg.utoronto.ca/~kmurray/air/aspdac2020_air.pdf',access='Full original paper via proceedings mirror; author URL returned404 to web open',locator='SectionsII.A andIV, Algorithm1',supports='Legal subtree retention, delay-degraded connection rip-up, multi-convergence improvement of existing routing. Present congestion resets while historical congestion persists.',comparison='These ingredients are prior art; our added controls concern crossing domains, per-net release, capacity-certified coordination and fixed-envelope whole-candidate decisions. No head-to-head AIR speed claim.'),
